const whitelist = {
  'focus_workspace': (args) => typeof args.index === 'number' && args.index >= 1 && args.index <= 10,
  'move_window_to_workspace': (args) => typeof args.index === 'number' && args.index >= 1 && args.index <= 10,
  'launch_app': (args) => ['code','firefox','foot','obsidian','telegram'].includes(args.app_name),
  'set_volume': (args) => typeof args.level === 'number' && args.level >= 0 && args.level <= 100,
  'set_brightness': (args) => typeof args.level === 'number' && args.level >= 0 && args.level <= 100,
  'query_jarvis_brain': (args) => typeof args.query === 'string' && args.query.length > 0,
  'system_power': (args) => ['lock','suspend','reboot','shutdown'].includes(args.mode)
};

let validActions = [];
try {
  const text = $json.candidates[0].content.parts[0].text;
  const parsed = JSON.parse(text);
  const actionsArr = Array.isArray(parsed.actions) ? parsed.actions : [];

  for (const item of actionsArr) {
    if (item && item.action && whitelist[item.action]) {
      if (whitelist[item.action](item.args || {})) {
        validActions.push({ action: item.action, args: item.args });
      }
    }
  }
} catch (e) {
  console.warn("Intent parsing error:", e);
}

return [{ json: { actions: validActions } }];
